using UnityEngine;

namespace AiOn.People
{
    /// <summary>
    /// Drives a person (Rocketbox avatar, Humanoid; PeopleBuilder). Animation names are the original's:
    /// idle, walk, brisk, run (one blend space by speed), carry, walker, sit, sitChair, talk, phone, wave, point, crouch,
    /// stairsUp, stairsDown, hurt, down, air; one-shot clips: punch, throw, pickup, vault, climb, land, hurt.
    /// The Animator controllers are generated by AiOn → Build People (one per clip set, see PersonClips: states named
    /// after the original's clips, a "Locomotion" blend tree on the float "Speed", one-shots on the "Action" layer).
    /// </summary>
    [RequireComponent(typeof(Animator))]
    public class PersonAnimator : MonoBehaviour
    {
        public const float WalkSpeed = 1.3f, BriskSpeed = 2.1f, RunSpeed = 3.9f;
        public const float Fade = 0.2f;
        /// <summary>Seconds of offset a full phase gives on a cross-fade (about one gait cycle).</summary>
        const float CycleSeconds = 1.1f;

        public string preset;
        [Tooltip("Animation shown when the scene starts.")]
        public string startAnim = "idle";
        [Tooltip("Cycle offset (0..1) when an animation starts, so people of a crowd do not move in lockstep (people.js seed phase).")]
        [Range(0, 1)] public float phase;
        [Tooltip("Gait speed correction for this body's size (AiOn → Build People measures it): the shared controller's walk, " +
                 "played on this avatar at this scale, covers ground at 1/gaitScale of the asked speed.")]
        public float gaitScale = 1f;

        Animator _animator;
        string _current, _arms, _hold;
        static readonly int SpeedId = Animator.StringToHash("Speed");
        static readonly int GaitId = Animator.StringToHash(PersonClips.GaitScaleParam);

        public string Current => _current;
        /// <summary>The arm pose layer's state now (PersonClips.ArmsNone when the clip's own arms show).</summary>
        public string Arms => _arms;

        /// <summary>
        /// What the hands hold that sets the arm pose: "cart" (both hands on the cart handle while standing or walking) or
        /// null. Sitting on the floor rests the hands by itself (PersonClips.ArmsFor).
        /// </summary>
        public string HoldPose
        {
            get => _hold;
            set { if (_hold == value) return; _hold = value; ApplyArms(false); }
        }

        void Awake()
        {
            Ready();
            if (Application.isPlaying) AiOn.Rendering.PeopleFill.Mark(gameObject); // the soft fill for faces in dark scenes
        }

        /// <summary>The animator, found on first use (edit-mode tools call SetAnim without Awake).</summary>
        bool Ready()
        {
            if (!_animator)
            {
                _animator = GetComponent<Animator>();
                if (!_animator) return false;
                _animator.applyRootMotion = false;
                if (Application.isPlaying) _animator.cullingMode = AnimatorCullingMode.CullUpdateTransforms;
            }
            return _animator.runtimeAnimatorController;
        }

        void OnEnable()
        {
            _current = null; _arms = null;
            if (Ready()) _animator.SetFloat(GaitId, gaitScale);
            SetAnim(startAnim, instant: true);
        }

        static bool IsGait(string name) => name == "walk" || name == "brisk" || name == "run";
        /// <summary>States whose speed (m/s) sets how fast the clip plays: the gaits and carry.</summary>
        public static bool TakesSpeed(string name) => IsGait(name) || name == "carry";

        /// <summary>Switches the looping animation. Gaits and carry take a speed in m/s (default: the gait's own speed).</summary>
        public void SetAnim(string name, float? speed = null, bool instant = false)
        {
            if (string.IsNullOrEmpty(name) || !Ready()) return;
            if (TakesSpeed(name))
            {
                _animator.SetFloat(SpeedId, speed ?? (name == "brisk" ? BriskSpeed : name == "run" ? RunSpeed : WalkSpeed));
                if (IsGait(name)) name = "Locomotion";
            }
            if (name != _current)
            {
                _current = name;
                if (instant) _animator.Play(name, 0, phase);
                else _animator.CrossFadeInFixedTime(name, Fade, 0, phase * CycleSeconds);
            }
            ApplyArms(instant);
        }

        /// <summary>Locomotion by speed alone: idle below 0.15 m/s, else the walk-brisk-run blend.</summary>
        public void Move(float speed)
        {
            if (!Ready()) return;
            if (speed < 0.15f) { SetAnim("idle"); return; }
            _animator.SetFloat(SpeedId, speed, 0.12f, Time.deltaTime);
            if (_current != "Locomotion") { _current = "Locomotion"; _animator.CrossFadeInFixedTime("Locomotion", Fade, 0, phase * CycleSeconds); }
            ApplyArms(false);
        }

        void ApplyArms(bool instant)
        {
            if (!Ready() || _current == null || _animator.layerCount <= PersonClips.ArmsLayer) return;
            var want = PersonClips.ArmsFor(_current, phase, _hold);
            if (want == _arms) return;
            _arms = want;
            if (instant) _animator.Play(want, PersonClips.ArmsLayer, 0f);
            else _animator.CrossFadeInFixedTime(want, 0.3f, PersonClips.ArmsLayer);
        }

        /// <summary>Holds the pose still (animator speed 0) from the start of the current state, or lets it run again.</summary>
        public void Hold(bool still)
        {
            if (!Ready()) return;
            if (still && _animator.speed != 0f)
            {
                _animator.Play(_current ?? "idle", 0, 0f);
                if (_animator.layerCount > PersonClips.ArmsLayer) { _animator.Play(PersonClips.ArmsNone, PersonClips.ArmsLayer, 0f); _arms = PersonClips.ArmsNone; }
                _animator.Update(0f);
                _animator.speed = 0f;
            }
            else if (!still && _animator.speed == 0f) _animator.speed = 1f;
        }

        public bool Held => _animator && _animator.speed == 0f;

        /// <summary>Plays a one-shot clip over the current animation, then returns to it.</summary>
        public void Play(string clip)
        {
            if (!Ready()) return;
            _animator.CrossFadeInFixedTime("clip_" + clip, 0.08f, 1);
        }
    }
}
